if [[ "$lang" == "en" ]]; then L_NOTAB="No tab found in Brave, Chrome or Chromium" L_NOTAB_SUB="Open a page in a supported browser, then try again" L_PROMPT_HEAD="Please take a look at this page." L_TITLE="Title" L_COPIED="Copied. Paste into Muse to send" L_PASTED="Tried to paste into Quick Chat - please check before sending" else L_NOTAB="対応ブラウザのタブが取得できませんでした" L_NOTAB_SUB="Brave / Chrome / Chromium でページを開いてから実行してください" L_PROMPT_HEAD="このページを見てください。" L_TITLE="タイトル" L_COPIED="コピーしました。貼り付けて送信してください" L_PASTED="Quick Chat へ貼り付けを試みました。確認してから送信してください" fi
