valid_url() { case "$1" in *://*|about:*|chrome:*|brave:*|file:*) return 0 ;; *) return 1 ;; esac }
if [[ "$mode" == "--list" ]]; then items="" for app in "${BROWSERS[@]}"; do out=$(get_tab "$app") [[ "$out" == *"$US"* ]] || continue title=$(trim "${out%%"$US"*}") url=$(trim "${out##*"$US"}") [[ -n "$url" ]] || continue if [[ -z "$title" ]]; then title="$url"; fi p=$(make_payload "$app" "$title" "$url") item=$(printf '{"title":%s,"subtitle":%s,"arg":%s,"valid":true,"variables":{"TABRELAY_BROWSER":%s,"TABRELAY_TITLE":%s,"TABRELAY_URL":%s}}' \ "$(json_escape "$title")" \ "$(json_escape "$app — $url")" \ "$(json_escape "$p")" \ "$(json_escape "$app")" \ "$(json_escape "$title")" \ "$(json_escape "$url")") if [[ -n "$items" ]]; then items="$items,$item"; else items="$item"; fi done if [[ -z "$items" ]]; then printf '{"items":[{"title":%s,"subtitle":%s,"valid":false}]}\n' \ "$(json_escape "$L_NOTAB")" "$(json_escape "$L_NOTAB_SUB")" exit 0 fi printf '{"items":[%s]}\n' "$items" exit 0 fi
# --send: 選択された項目の payload を最優先し、無ければ変数、最後に実タブを取り直す title="" url="" browser="" if [[ -n "$payload" && "$payload" == *.*.* ]]; then pb="${payload%%.*}" rest="${payload#*.}" pt="${rest%%.*}" pu="${rest#*.}" d_title=$(b64d "$pt") d_url=$(b64d "$pu") if valid_url "$d_url"; then browser=$(b64d "$pb") title="$d_title" url="$d_url" fi fi if [[ -z "$url" && -n "${TABRELAY_URL:-}" ]] && valid_url "${TABRELAY_URL:-}"; then browser="${TABRELAY_BROWSER:-}" title="${TABRELAY_TITLE:-}" url="${TABRELAY_URL:-}" fi if [[ -z "$url" ]]; then for app in "${BROWSERS[@]}"; do out=$(get_tab "$app") [[ "$out" == *"$US"* ]] || continue t=$(trim "${out%%"$US"*}") u=$(trim "${out##*"$US"}") if [[ -n "$u" ]]; then browser="$app"; title="$t"; url="$u" break fi done fi if [[ -z "$url" ]]; then echo "$L_NOTAB" exit 1 fi if [[ -z "$title" ]]; then title="$url"; fi { echo "$L_PROMPT_HEAD" echo echo "$L_TITLE: $title" echo "URL: $url" } | pbcopy # Muse Quick Chat（Option+Space）を開く。アクセシビリティ許可が無い場合は静かに失敗する # Open Muse Quick Chat (Option+Space). Fails silently without the Accessibility permission. osascript -e 'tell application "System Events" to keystroke " " using {option down}' >/dev/null 2>&1 || true if [[ "${TABRELAY_AUTO_PASTE:-0}" == "1" ]]; then sleep 0.9 osascript -e 'tell application "System Events" to keystroke "v" using {command down}' >/dev/null 2>&1 || true echo "$L_PASTED: $title" else echo "$L_COPIED: $title" fi
